#include <stdio.h>
#include <string.h>

int main() {
    char s[101];
    scanf("%s", s);

    char l[500001];
    scanf("%s", l);

    unsigned long long sLen = strlen(s);
    unsigned long long lLen = strlen(l);

    int i = 0;
    int j = 0;

    while(i < sLen && j < lLen) {
        if(s[i] == l[j]) {
            i++;
        }
        j++;
    }

    printf("%d\n", i == sLen ? j - 1 : -1);

    return 0;
}
